import{_ as a,o as n,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Configuración de inicio rápido","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/quick-launch.md","filePath":"es-ES/user-guide/settings/quick-launch.md","lastUpdated":1788085660000}'),l={name:"es-ES/user-guide/settings/quick-launch.md"};function r(s,e,t,d,c,u){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="configuracion-de-inicio-rapido" tabindex="-1">Configuración de inicio rápido <a class="header-anchor" href="#configuracion-de-inicio-rapido" aria-label="Permalink to &quot;Configuración de inicio rápido&quot;">​</a></h1><p>Inicio rápido es el panel de lanzamiento que aparece debajo de la ventana de búsqueda rápida cuando el cuadro de búsqueda está vacío. Combina elementos gestionados manualmente con fuentes de datos dinámicas seleccionadas, como Favoritos e Historial.</p><h2 id="_1-interruptor-principal" tabindex="-1">1. Interruptor principal <a class="header-anchor" href="#_1-interruptor-principal" aria-label="Permalink to &quot;1. Interruptor principal&quot;">​</a></h2><ul><li><strong>Activar el panel de inicio rápido</strong>: Activa el panel. Solo aparece en la ventana de búsqueda rápida cuando la consulta está vacía y al menos una fuente contiene datos disponibles.</li><li>Si se desactiva, el panel no carga ninguna fuente.</li><li>La altura se calcula a partir de la fuente con más elementos y no supera la altura máxima del área de resultados de la ventana de búsqueda rápida.</li></ul><h2 id="_2-elementos-manuales" tabindex="-1">2. Elementos manuales <a class="header-anchor" href="#_2-elementos-manuales" aria-label="Permalink to &quot;2. Elementos manuales&quot;">​</a></h2><p>Abre <strong>Configuración → Inicio rápido → Inicio rápido</strong> para gestionar tus elementos:</p><ul><li>Añade archivos, carpetas, URL o rutas de Windows Shell. Las variables de entorno se expanden al comprobar el destino.</li><li>El nombre visible es opcional. Si queda vacío, Lertaro lo genera a partir del destino.</li><li>Los botones para explorar archivos y carpetas permiten seleccionar varios elementos a la vez; cada destino válido y no duplicado se añade como una entrada independiente.</li><li>Usa el controlador de arrastre para cambiar el orden. Al pulsar editar, la misma fila se convierte en un editor en línea con controles para guardar o cancelar; el control de eliminar quita el elemento.</li><li>Los destinos que no estén disponibles se omiten temporalmente y vuelven a aparecer cuando están disponibles.</li></ul><h2 id="_3-fuentes-de-datos" tabindex="-1">3. Fuentes de datos <a class="header-anchor" href="#_3-fuentes-de-datos" aria-label="Permalink to &quot;3. Fuentes de datos&quot;">​</a></h2><p>Abre <strong>Configuración → Inicio rápido → Fuentes de datos</strong> para elegir fuentes dinámicas:</p><ul><li>Las fuentes proceden de los proveedores de pestañas del Panel rápido instalados. Así Inicio rápido reutiliza Favoritos, Historial, Historial de Windows, Último directorio, Archivos recientes y futuras fuentes de plugins sin duplicar sus datos.</li><li>Una fuente está activada por defecto cuando existe su proveedor. Solo se guardan en la configuración las fuentes desactivadas explícitamente.</li><li>Solo se crea una pestaña para una fuente activada que devuelva datos en ese momento. Las fuentes vacías se ocultan.</li><li>Si no hay datos en ningún elemento manual ni fuente dinámica, el panel de Inicio rápido se oculta.</li></ul><h2 id="_4-interaccion-con-el-panel" tabindex="-1">4. Interacción con el panel <a class="header-anchor" href="#_4-interaccion-con-el-panel" aria-label="Permalink to &quot;4. Interacción con el panel&quot;">​</a></h2><ul><li>El número de columnas se adapta al ancho de la barra de búsqueda.</li><li>Si solo hay una fuente, el indicador inferior de fuentes se oculta.</li><li>Con varias fuentes, la franja inferior muestra un punto por fuente. El punto seleccionado es azul y los demás grises; al pasar el ratón por encima, el punto se expande para mostrar el nombre de la fuente.</li><li>Mantén pulsada la tecla <strong>Shift</strong> y usa la rueda del ratón sobre el panel para recorrer las fuentes. La fuente seleccionada reproduce brevemente la misma animación de expansión.</li><li>Al empezar a escribir una consulta, el panel se oculta.</li></ul>',12)])])}const f=a(l,[["render",r]]);export{m as __pageData,f as default};
